const d = $input.first().json.data;
const r = d.repository;
const lines = [];
lines.push(`📋 **Omnimopolys daily report** – ${new Date().toISOString().slice(0, 10)}`);
lines.push(`Open issues: ${r.open.totalCount} · Bugs: ${r.bugs.totalCount} · Agent working: ${r.working.totalCount} · Open PRs: ${r.prs.totalCount}`);
for (const m of r.milestones.nodes) lines.push(`🏁 ${m.title}: ${Math.round(m.progressPercentage)}%`);
lines.push(`\n✅ Merged last 24h: ${d.merged.issueCount}`);
for (const p of d.merged.nodes) lines.push(`• #${p.number} ${p.title}`);
if (r.blocked.totalCount) {
  lines.push(`\n🙋 Needs a human: ${r.blocked.totalCount}`);
  for (const i of r.blocked.nodes) lines.push(`• #${i.number} ${i.title} <${i.url}>`);
}
return [{ json: { message: lines.join('\n').slice(0, 1990) } }];
